/* From Uiverse.io by Subaashbala  - Tags: simple, neumorphism, button */
.__UIV_SCOPE__ .button {
  cursor: pointer;
  position: relative;
  border-radius: 55px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 15px;
  gap: 8px;
  font-size: 1rem;
  font-weight: 900;
  background-color: white;
  border: none;
  background: linear-gradient(to bottom, #ecefee, #fff);
  transition: all 500ms;
}
.__UIV_SCOPE__ .button::after {
  content: "";
  position: absolute;
  width: 105%;
  height: 115%;
  background: linear-gradient(to top, #ecefeeb4, #fff);
  z-index: -1;
  top: 50%;
  left: 50%;
  border-radius: 15px;
  padding: 2px;
  transform: translate(-50%, -50%);
  border: 2px solid #d5d6d5;
  border-bottom: 3px solid #7b7d7cc0;
  border-left: 2px solid #b5b5b5;
  border-right: 2px solid #b5b5b5;
  box-shadow: 0px 20px 45px #b5b9b8;
}
.__UIV_SCOPE__ .icon svg {
  width: 1.18rem;
  height: auto;
  vertical-align: middle;
}
.__UIV_SCOPE__ .icon path {
  stroke-width: 5px;
}
